<template><view class="page"><view class="glass form"><text class="h1">登录</text><input v-model="account" placeholder="用户名/邮箱"/><input v-model="password" placeholder="密码" password/><button class="btn" @click="login">登录</button><button @click="demo">使用演示账号</button></view></view></template><script setup>import { ref } from 'vue'; import { useUserStore } from '../../store/user'; const store=useUserStore(); const account=ref('demo'); const password=ref('demo123'); async function login(){await store.login(account.value,password.value); uni.switchTab({url:'/pages/index/index'})} function demo(){account.value='demo';password.value='demo123';login()}</script><style scoped>.form{padding:40rpx;margin:80rpx 24rpx}.h1{display:block;font-size:50rpx;font-weight:900;margin-bottom:30rpx}.form input{background:#fff;border-radius:22rpx;padding:22rpx;margin:16rpx 0}</style>
